from vh import *
setc('Pediatric asthma exacerbation', 'presentation',
     '9-year-old boy with eczema and a mother with hay fever: 10 hours of wheeze and breathlessness after a 3-day cold, not relieved by one home albuterol nebulizer. Speaks in short phrases with suprasternal retractions; RR 38, HR 128, SpO2 90%; expiratory wheeze in all fields.')
setc('Epiglottitis', 'presentation',
     '2-year-old girl who has never been vaccinated: 2 hours of T 38.9 C and harsh, noisy breathing in. Toxic-looking, with a muffled cry, drooling, suprasternal retractions; no cough, no witnessed choking, no sick contacts; lungs clear.')
setb('Epiglottitis in an unimmunized toddler', 'presentation',
     '3-year-old boy whose parents declined all vaccines: well at bedtime, woke at 2 a.m. with T 39.4 C, sore throat and a soft high-pitched noise on breathing in. Refuses to swallow, saliva runs from his mouth, voice muffled, no cough; HR 160, SpO2 94%; lungs clear.')
setb('Croup (laryngotracheobronchitis)', 'presentation',
     '2-year-old boy in October whose sister had a cold last week: 2 days of runny nose and low fever, then a harsh cough worse at night and a high-pitched noise on breathing in that is louder when he cries. Hoarse voice; T 38.1 C, RR 34, SpO2 96%; not toxic, drinking well, no drooling.')
setb('Bronchiolitis in an infant', 'presentation',
     '2-month-old boy born at 32 weeks, in December, whose brother in daycare has a cold: 2 days of runny nose, now coughing, grunting and taking half his usual feeds. T 38.1 C, RR 64, SpO2 89%; subcostal retractions, wheeze and fine crackles on both sides.')
